import React, { useState, useEffect, useCallback } from 'react';
import { BrowserRouter as Router, Routes, Route, useNavigate, useLocation } from 'react-router-dom';
import './App.css';
import Login from './pages/login';
import MasterPage from './pages/MasterPage';
import CentrosPorRegion from './pages/CentrosPorRegion';
import ProyectoPage from './pages/ProyectoPage';
import './pages/ProyectoPage.css';
import UsuariosPage from './pages/UsuariosPage';
import Ajuste from './pages/ajuste';
import GeminiChat from './components/GeminiChat';

function App() {
  const [user, setUser] = useState(null);
  const [centros, setCentros] = useState([]);
  const [showTimeoutWarning, setShowTimeoutWarning] = useState(false);
  const [timeoutCountdown, setTimeoutCountdown] = useState(60); // 60 segundos de advertencia

  // Hook de navegación
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    // Cargar usuario desde localStorage si existe
    const userData = JSON.parse(localStorage.getItem('user'));
    const centrosData = JSON.parse(localStorage.getItem('centros')) || [];
    setUser(userData);
    setCentros(centrosData);
  }, []);

  const handleLogout = useCallback(() => {
    // Limpiar localStorage
    localStorage.removeItem('user');
    localStorage.removeItem('centros');
    // Limpiar estado
    setUser(null);
    setCentros([]);
    // Redirigir a la página de login (raíz)
    window.location.href = '/';
  }, []);

  const handleExtendSession = useCallback(() => {
    // Ocultar advertencia y resetear timer
    setShowTimeoutWarning(false);
    setTimeoutCountdown(60);
    // El timer se reseteará automáticamente con los event listeners
  }, []);

  // Sistema de timeout de inactividad (10 minutos)
  useEffect(() => {
    if (!user) return; // Solo activar si hay usuario logueado

    let inactivityTimer;
    let warningTimer;
    let countdownInterval;
    const INACTIVITY_TIME = 10 * 60 * 1000; // 10 minutos en milisegundos
    const WARNING_TIME = 60 * 1000; // 1 minuto de advertencia antes de cerrar

    const resetTimer = () => {
      // Limpiar timers existentes
      if (inactivityTimer) clearTimeout(inactivityTimer);
      if (warningTimer) clearTimeout(warningTimer);
      if (countdownInterval) clearInterval(countdownInterval);
      
      // Ocultar advertencia si estaba visible
      setShowTimeoutWarning(false);
      setTimeoutCountdown(60);

      // Iniciar nuevo timer de inactividad
      inactivityTimer = setTimeout(() => {
        // Mostrar advertencia 1 minuto antes de cerrar
        setShowTimeoutWarning(true);
        setTimeoutCountdown(60);

        // Iniciar countdown
        countdownInterval = setInterval(() => {
          setTimeoutCountdown((prev) => {
            if (prev <= 1) {
              clearInterval(countdownInterval);
              return 0;
            }
            return prev - 1;
          });
        }, 1000);

        // Timer para cerrar sesión después de la advertencia
        warningTimer = setTimeout(() => {
          handleLogout();
        }, WARNING_TIME);
      }, INACTIVITY_TIME - WARNING_TIME);
    };

    // Eventos que resetean el timer
    const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart', 'click'];
    
    events.forEach((event) => {
      document.addEventListener(event, resetTimer, true);
    });

    // Iniciar el timer
    resetTimer();

    // Limpiar al desmontar o cuando el usuario cambia
    return () => {
      events.forEach((event) => {
        document.removeEventListener(event, resetTimer, true);
      });
      if (inactivityTimer) clearTimeout(inactivityTimer);
      if (warningTimer) clearTimeout(warningTimer);
      if (countdownInterval) clearInterval(countdownInterval);
    };
  }, [user, handleLogout]);

  // Redirección automática según el rol
  useEffect(() => {
    // Permitir acceso directo a la página de proyecto
    if (location.pathname.startsWith('/proyecto/')) {
      return;
    }
    if (user) {
      console.log('App: Redirección automática - Usuario:', user.rol, 'Path:', location.pathname);
      
      // No redirigir si estamos en la página de centros por región
      if (location.pathname === '/centros-por-region') {
        console.log('App: Permitiendo acceso a centros-por-region');
        return;
      }
      
      // super_admin: puede acceder a todas las rutas
      if (user.rol === 'super_admin') {
        // Permitir acceso a todas las rutas
        return;
      }
      
      // admin: puede acceder a inicio, proyectos y usuarios, pero NO a ajuste
      if (user.rol === 'admin') {
        if (location.pathname === '/ajuste') {
          console.log('App: Admin no puede acceder a ajuste, redirigiendo a /');
          navigate('/');
        }
        return;
      }
      
      // trabajador: puede acceder a inicio y proyectos asignados
      if (user.rol === 'trabajador') {
        if (location.pathname === '/ajuste' || location.pathname === '/usuarios') {
          console.log('App: Trabajador no puede acceder a ajuste/usuarios, redirigiendo a /');
          navigate('/');
        }
        return;
      }
      
      // visita: solo puede ver inicio y proyectos (sin acceso a proyectos)
      if (user.rol === 'visita') {
        if (location.pathname.startsWith('/proyecto/') || 
            location.pathname === '/ajuste' || 
            location.pathname === '/usuarios') {
          console.log('App: Visita no puede acceder a proyectos/ajuste/usuarios, redirigiendo a /');
          navigate('/');
        }
        return;
      }
    }
  }, [user, centros, navigate, location.pathname]);

  const handleUsuariosClick = (event) => {
    event.preventDefault();
    navigate('/usuarios');
  };

  if (!user) {
    // Solo el login es condicional
    return <Login setUser={setUser} setCentros={setCentros} />;
  }

  return (
    <>
      {/* Modal de advertencia de timeout */}
      {showTimeoutWarning && user && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0, 0, 0, 0.75)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 100000,
          backdropFilter: 'blur(4px)'
        }}>
          <div style={{
            background: '#fff',
            borderRadius: '16px',
            padding: '2rem',
            width: '450px',
            maxWidth: '90vw',
            border: '3px solid #ffc107',
            boxShadow: '0 8px 32px rgba(0, 0, 0, 0.3)',
            textAlign: 'center'
          }}>
            <div style={{
              width: '64px',
              height: '64px',
              background: 'linear-gradient(135deg, #ffc107 0%, #ff9800 100%)',
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '32px',
              color: 'white',
              margin: '0 auto 1.5rem'
            }}>
              <i className="fa fa-clock"></i>
            </div>
            <h3 style={{ margin: '0 0 1rem 0', fontSize: '1.5rem', color: '#333', fontWeight: 700 }}>
              Sesión por Expirar
            </h3>
            <p style={{ fontSize: '1rem', color: '#666', marginBottom: '1.5rem', lineHeight: '1.6' }}>
              Tu sesión se cerrará automáticamente por seguridad en:
            </p>
            <div style={{
              fontSize: '2.5rem',
              fontWeight: 700,
              color: '#ffc107',
              marginBottom: '1.5rem',
              fontFamily: 'monospace'
            }}>
              {timeoutCountdown}s
            </div>
            <p style={{ fontSize: '0.9rem', color: '#999', marginBottom: '2rem' }}>
              Por favor, confirma que sigues activo para continuar
            </p>
            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center' }}>
              <button
                onClick={handleLogout}
                style={{
                  padding: '0.75rem 1.5rem',
                  border: '1.5px solid #dc3545',
                  background: '#fff',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontSize: '0.95rem',
                  fontWeight: 600,
                  color: '#dc3545'
                }}
              >
                Cerrar Sesión
              </button>
              <button
                onClick={handleExtendSession}
                style={{
                  padding: '0.75rem 1.5rem',
                  border: 'none',
                  background: 'linear-gradient(135deg, #28a745 0%, #20c997 100%)',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontSize: '0.95rem',
                  fontWeight: 600,
                  color: '#fff',
                  boxShadow: '0 4px 12px rgba(40, 167, 69, 0.3)'
                }}
              >
                <i className="fa fa-check" style={{ marginRight: '0.5rem' }}></i>
                Continuar Sesión
              </button>
            </div>
          </div>
        </div>
      )}

      <Routes>
        <Route path="/" element={<MasterPage user={user} centros={centros} onLogout={handleLogout} />} />
        <Route path="/centros-por-region" element={<CentrosPorRegion user={user} centros={centros} onLogout={handleLogout} />} />
        <Route path="/ajuste" element={<Ajuste user={user} />} />
        <Route path="/proyecto/:proyectoId" element={<ProyectoPage />} />
        <Route path="/usuarios" element={<UsuariosPage user={user} />} />
      </Routes>
      {user && <GeminiChat />}
    </>
  );
}

// Envolver App con Router para que useNavigate funcione
function AppWithRouter() {
  return (
    <Router>
      <App />
    </Router>
  );
}

export default AppWithRouter; 